function normalizeApiPath(base: string, endpoint: string): string {
  const combined = (base + '/' + endpoint).replace(/\/+/g, '/');
  let trimmed = combined.replace(/\/+$/, '');
  if (!trimmed.startsWith('/')) trimmed = '/' + trimmed;
  return trimmed || '/';
}

