function resolveModuleImport(specifier: string, defaultExt: string = '.js'): string {
  const lastSlash = specifier.lastIndexOf('/');
  const filename = lastSlash === -1 ? specifier : specifier.slice(lastSlash + 1);
  if (filename.includes('.')) return specifier;
  return specifier + defaultExt;
}

