function applyDefaults<T extends Record<string, unknown>>(provided: Partial<T>, defaults: T): T {
  const out = { ...defaults };
  for (const [k, v] of Object.entries(provided)) {
    if (v !== undefined) {
      (out as any)[k] = v;
    }
  }
  return out;
}

