async function settleAllBatch<T>(tasks: (() => Promise<T>)[]): Promise<{ succeeded: T[]; failed: string[] }> {
  const results = await Promise.allSettled(tasks.map(t => t()));
  const succeeded: T[] = [];
  const failed: string[] = [];
  for (const r of results) {
    if (r.status === 'fulfilled') succeeded.push(r.value);
    else failed.push(r.reason?.message || String(r.reason));
  }
  return { succeeded, failed };
}

