function maskSensitiveFields(data: Record<string, unknown>, sensitiveKeys: string[] = ['password', 'token', 'secret']): Record<string, unknown> {
  const sensitive = new Set(sensitiveKeys.map(k => k.toLowerCase()));
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(data)) {
    if (sensitive.has(k.toLowerCase())) {
      out[k] = '***REDACTED***';
    } else {
      out[k] = v;
    }
  }
  return out;
}

