function sortEntities<T extends Record<string, any>>(items: T[], field: keyof T, order: 'asc' | 'desc' = 'asc'): T[] {
  return [...items].sort((a, b) => {
    const valA = a[field];
    const valB = b[field];
    let cmp = 0;
    if (typeof valA === 'string' && typeof valB === 'string') {
      cmp = valA.localeCompare(valB);
    } else if (valA < valB) {
      cmp = -1;
    } else if (valA > valB) {
      cmp = 1;
    }
    return order === 'desc' ? -cmp : cmp;
  });
}
